SELECT id, CAST(a AS DECIMAL(10,2)) * CAST(a AS DECIMAL(10,2)) AS sq, CAST(a AS DECIMAL(10,2)) * CAST(b AS DECIMAL(19,0)) AS ab, CAST(b AS DECIMAL(19,0)) * CAST(b AS DECIMAL(19,0)) AS bb, CAST(a AS DECIMAL(10,2)) * 0.125 AS lit, CAST(a AS DECIMAL(10,2)) * (1 - CAST(a AS DECIMAL(10,2))) AS disc FROM t ORDER BY id;
